            sql: '{{#switch (default param.duplicate_action "Keep first record")}}{{#case "Drop all duplicated records"}}COUNT(*) OVER (PARTITION BY {{#each (duplicateKeys param legacy=true) separator=", "}}{{field sourceFile fieldName alias=sourceAlias}}{{/each}}) AS [Duplicate Count] -- keep rows where [Duplicate Count] = 1{{/case}}{{#case "Keep last record"}}ROW_NUMBER() OVER (PARTITION BY {{#each (duplicateKeys param legacy=true) separator=", "}}{{field sourceFile fieldName alias=sourceAlias}}{{/each}} ORDER BY (SELECT NULL)) AS [Duplicate Rank], COUNT(*) OVER (PARTITION BY {{#each (duplicateKeys param legacy=true) separator=", "}}{{field sourceFile fieldName alias=sourceAlias}}{{/each}}) AS [Duplicate Count] -- keep rows where [Duplicate Rank] = [Duplicate Count]{{/case}}{{#default}}ROW_NUMBER() OVER (PARTITION BY {{#each (duplicateKeys param legacy=true) separator=", "}}{{field sourceFile fieldName alias=sourceAlias}}{{/each}} ORDER BY (SELECT NULL)) AS [Duplicate Rank] -- keep rows where [Duplicate Rank] = 1{{/default}}{{/switch}}',
